mapper.sql:
c.deleted_at = 0 AND c.platform = #{query.platform}

    AND c.external_card_id LIKE CONCAT('%', #{query.cardId}, '%')


    AND (c.card_name LIKE CONCAT('%', #{query.cardName}, '%')
        OR c.advertisement_account_id LIKE CONCAT('%', #{query.cardName}, '%'))


    AND FIND_IN_SET(c.masked_pan, #{query.cardNo}) > 0


    AND LOWER(c.card_status) = LOWER(#{query.status})


    AND c.period_max_consume_amount = #{query.periodMaxConsumeAmount}


    AND COALESCE(c.provider_created_at, c.created_at) >= #{query.startDate}


    AND COALESCE(c.provider_created_at, c.created_at) < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)

mapper.update:
UPDATE card_station_limit_rule
SET auto_adjust_enabled = #{enabled}, updated_by = #{updatedBy}
WHERE id = #{id} AND scope_key = 'global' AND deleted_at = 0
